from functools import lru_cache
import math

class Checker:
    def soupServings(self, n, result):
        if n > 5000:
            return abs(result - 1.0) <= 1e-5
        units = math.ceil(n / 25)

        @lru_cache(None)
        def calc(a, b):
            if a <= 0 and b <= 0:
                return 0.5
            if a <= 0:
                return 1.0
            if b <= 0:
                return 0.0
            return 0.25 * (calc(a - 4, b) + calc(a - 3, b - 1) + calc(a - 2, b - 2) + calc(a - 1, b - 3))

        expected = calc(units, units)
        return abs(result - expected) <= 1e-5
